-- wger exercises, part 3 (generated by scripts/import_wger.py; CC licences, author per row).
-- Existing exercises win: a clashing name or id is skipped.
insert into public.exercises (id, name, main_muscles, form_instructions, equipment, source, license, author, source_url)
values
  ('18104387-4567-4c1e-8d03-db0b274646dd', 'Leg Press on Hackenschmidt Machine', 'Quads', null, null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/375/view/'),
  ('0cc9c8ed-57f1-42c3-a4c4-6e57e6a1b878', 'Leg Press Toe Press', 'Calves', 'Move the leg press using your calves by placing your feet at the bottom of the platform.', null, 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1515/view/'),
  ('5f0b757c-0d6a-430b-9d5e-3bfba202878e', 'Leg Presses (narrow)', 'Quads', 'The exercise is very similar to the wide leg press:
Sit on the machine and put your feet on the platform so far apart  that you could just put another foot in between them. The feet are parallel and point up.
Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/373/view/'),
  ('661287d4-d1dc-485c-896b-73f90b000536', 'Leg Presses (wide)', 'Quads', 'Sit on the machine and put your feet on the platform, a bit more than shoulder wide. The feet are turned outwards by a few degrees.
Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/374/view/'),
  ('c2078aac-e4e2-4103-a845-6252a3eb795e', 'Leg Raise', 'Obliquus externus abdominis, Abs', 'The leg raise is a strength training exercise which targets the iliopsoas (the anterior hip flexors). Because the abdominal muscles are used isometrically to stabilize the body during the motion, leg raises are also often used to strengthen the rectus abdominis muscle and the internal and external oblique muscles.', null, 'wger', 'CC0', 'BFad07', 'https://wger.de/en/exercise/376/view/'),
  ('b2025776-2397-4de7-a49e-296321169481', 'Leg raises pull up bar', 'Abs', 'with a firm grip with both hands on the bar, raise your outstretched legs, until you reach a 90° angle with your torso.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/979/view/'),
  ('9e34bc01-9cec-4ee2-a9bb-9c937a471c24', 'Leg Raises, Lying', 'Abs', 'Lay down on a bench and hold onto the recliner with your hands to keep you stable. Hold your legs straight and lift them till they make an angle of about 45°. Make a short pause of 1 sec. and go slowly down to the initial position. To increase the intensity you can make a longer pause of 7 sec. every 5th time.', 'Gym mat', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/377/view/'),
  ('5f514f9e-6bd9-408e-85b2-c25eb04af33b', 'Leg Raises, Standing', 'Abs', 'Put your forearms on the pads on the leg raise machine, the body is hanging freely. Lift now your legs with a fast movement as high as you can, make a short pause of 1sec at the top, and bring them down again. Make sure that during the exercise your body does not swing, only the legs should move.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/378/view/'),
  ('1fae7d45-0731-4640-8809-94c76b836571', 'Leg Swings (Front–Back)', 'Hamstrings', 'Stand tall next to a wall or stable support. Swing one leg forward and backward in a controlled motion, keeping the torso upright and the core engaged. Alternate legs after completing the repetitions.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Jhonatan', 'https://wger.de/en/exercise/1670/view/'),
  ('19d10f51-3e53-4d8f-b283-1d8d9a7d3543', 'Leg Wheel', 'Abs', 'Lay on the back and lift legs in perpendicular fashion, keeping the knees together.
Start making small circles in one direction with both of your knees with very small range of motion, focusing on abs and keeping your back in contact with the floor.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1909/view/'),
  ('2e96e572-ddb4-4251-a812-ccf03ea677a6', 'Legend Chest Press', 'Chest', 'Plate-loaded chest press machine from Legend Fitness LeverEdge line.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1918/view/'),
  ('e4804b7c-50af-4947-821f-3750718ffe65', 'Legend Incline Bench Press', 'Chest', 'Incline bench press on the Legend Fitness LeverEdge machine. Adjust the seat, release the lever and press until your arms are extended, then lower under control.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1773/view/'),
  ('85cb0a1b-250e-400b-892b-50186dac0777', 'lento avanti seduto', 'Shoulders', 'slow controlled seated forward exercise with dumbbells', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Cf', 'https://wger.de/en/exercise/1967/view/'),
  ('82aec7f9-ee03-4b24-8994-f6bde07c6a41', 'Leverage Machine Chest Press', 'Chest', 'Be sure to adjust seat height so that the handles are towards the bottom of your pectorals.', null, 'wger', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/379/view/'),
  ('fd595232-b9ad-4216-bba1-92298f993ea9', 'Leverage Machine Iso Row', 'Lats', 'Adjust seat height so that the handles are at the bottom of your pectorals or just below.', null, 'wger', 'CC-BY-SA 3', 'tuckerm', 'https://wger.de/en/exercise/380/view/'),
  ('9816dc3a-9739-4c70-bce0-4131f889e4f2', 'Levitation Crunch', 'Abs', 'For
this top down movement, we’re trying to move the upper torso without moving the
lower torso. Start lying on the ground with feet flat on the floor and crossed
arms above your head with hands behind head. Lift upper body up and clear your
shoulder blades off the ground and then hold and pause at the top for a one or
two count. Try to make the upper abs work and hold that contraction for 10 good
quality reps.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1478/view/'),
  ('2cd0135b-8ef1-4bca-8a75-5fe2f507bee6', 'Limber 11', null, 'Limber 11
Source: Joe DeFranco
1. Foam Roll IT Band [soft_tissue] - 10-15 passes
2. Foam Roll Adductors [soft_tissue] - 10-15 passes
3. SMR Glutes (lax ball) [soft_tissue] - 30 sec-2 min
4. Bent-knee Iron Cross [dynamic] - 5-10 reps each side
5. Roll-overs into V-sits [dynamic] - 10 reps
6. Rocking Frog Stretch [dynamic] - 10 reps
7. Fire Hydrant Circles [dynamic] - 10 forward / 10 backward
8. Mountain Climbers [dynamic] - 10 reps each leg
9. Cossack Squats [dynamic] - 5-10 reps each side
10. Seated Piriformis Stretch [isometric] - 20-30 sec each side
11. Rear-foot-elevated Hip Flexor Stretch [dynamic + 3s hold] - 5-10 reps each side', null, 'wger', 'CC-BY-SA 4', 'Pete-E automation', 'https://wger.de/en/exercise/1949/view/'),
  ('692d294d-925d-4a4e-8059-02a1a0ffdae4', 'Long Lunge Pulse Stretch', null, '- Hold the resistance band (or any other rope-like object, the elasticity is not necessary) above your head, between your hands, with your arms straight. Pull it taught to engage your lats.
- Step forwards into a lunge, dropping until your knee is almost touching the floor.
- Slowly and controlledly pulse your body up and down by about an inch. Repeat for required reps.
- Repeat for other leg.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/2526/view/'),
  ('a7e6c20a-6ddc-4401-9935-ace2d02e3995', 'Long-Pulley (low Row)', 'Lats', 'Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/394/view/'),
  ('77c98954-b50d-46f0-9912-3981f856d5a6', 'Long-Pulley, Narrow', 'Lats', 'The exercise is the same as the regular long pulley, but with a narrow grip:
Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/395/view/'),
  ('183e7279-f052-4c70-8381-bbbda3bb9afe', 'Low Box Squat - Wide Stance', 'Glutes, Quads', 'Unrack the bar and set your stance wide, beyond your hips.  Push your hips back and sit down to a box that takes you below parallel.  Sit completely down, do not touch and go.  Then explosively stand up.  Stay tight in your upper back and torso throughout the movement.', 'Barbell', 'wger', 'CC-BY-SA 4', 'taylorbarbell', 'https://wger.de/en/exercise/397/view/'),
  ('d5116fbd-bf14-492a-86b3-140035cb48b2', 'Low Pulley Cable Fly', 'Chest', 'Adjust the cable machine: Set the pulley to the lowest setting possible.
Choose your handles: You can use neutral grip handles (palms facing each other) or straight handles depending on your preference. Neutral grip might be easier on your wrists.
Stand with proper form: Stand with your feet shoulder-width apart, knees slightly bent, and core engaged. Maintain a slight arch in your lower back throughout the exercise.
Grip the handles: Grab the handles with your chosen grip and step back a small step or two until there''s slight tension on the cables.
Initiate the movement: Keep your elbows slightly bent throughout the exercise. Imagine you''re giving someone a big hug. Squeeze your chest muscles as you bring your hands together in front of your chest.
Control the movement: Focus on squeezing your chest muscles rather than using your arms to pull the handles.
Peak contraction: Briefly hold the squeeze at the top of the movement with your hands together at chest level.
Return slowly: Slowly release the tension and return the handles back down to the starting position with your arms slightly extended but not locked out.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'FEFFO', 'https://wger.de/en/exercise/1270/view/'),
  ('ac6e6a09-5175-4fea-9e56-e2ff3c00b0f2', 'Low-Cable Cross-Over - NB', 'Chest', 'The low-cable cross-over is an isolation movement that uses a cable stack to target the upper portion of the pectoral muscles. It is common in upper-body and chest-focused muscle-building workouts, often in combination with presses or flyes from other angles to target all portions of the chest.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'JackSparrow', 'https://wger.de/en/exercise/1296/view/'),
  ('50a8f1f6-6772-4319-be9d-3bad1374dadf', 'Lower Back Extensions', null, '- Engage the muscles
- Lift your bottom slightly
- Controlled movement
- Slow movement
- Don''t use momentum
- Keep your upper body straight', null, 'wger', 'CC-BY-SA 4', 'Anastasious', 'https://wger.de/en/exercise/1348/view/'),
  ('558b3385-f1a2-47d2-8473-e1be2c7726aa', 'Lunge with Twist Stretch', null, 'View the video to undestand the exercise', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1868/view/'),
  ('3284fd27-5402-4821-9c32-29066d4e2667', 'Lunges', 'Glutes, Quads', 'Starting position:
Stand with back straight.
Steps:
- Take a large step forward with your left leg.
- Bring your pelvis down until you almost touch the floor with your right knee.
- Bring your pelvis back up.
- Return to the starting position by stepping back.
- Repeat, switching legs each time.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/984/view/'),
  ('861f7396-f34e-486c-a903-3c326086f920', 'Lying Dumbbell Curls', 'Biceps', 'Take a
dumbbell in each hand and lie backwards on a bench, similar to a classic chest press.
Let your arms hang down at your sides, with the dumbbells possibly touching the
floor. Now start to lift the dumbbells upwards until your forearms are
perpendicular to the ceiling. Slowly lower the dumbbells until they almost
touch the floor again. Keep your ellbows in place to minimize cheating.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1530/view/'),
  ('dab7400b-e86e-4224-bcea-4a915dc928e0', 'Lying Dumbbell Row SS Seated Shrug', 'Lats, Trapezius', 'laying on the stomach on a bench with slight angle', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/923/view/'),
  ('76b6e798-e484-4606-aa64-8421aea51e88', 'Lying Figure Four Stretch', 'Glutes', 'Lie on your back with both knees bent and your feet flat on the floor. Cross one ankle over the opposite knee so that your legs form a figure four.
Reach through the gap and hold the back of the thigh of the lower leg, or its shin, and gently pull it towards your chest until you feel a stretch in the glute and outer hip of the crossed leg. Keep your head and lower back on the floor and let the crossed knee open outwards. Hold the stretch and breathe calmly, then switch sides.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1869/view/'),
  ('b5529305-04a2-4ca2-af6a-4a67d3e4aca4', 'Lying Hamstring Stretch with Band', null, 'View the video to undestand the exercise', 'Resistance band', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1870/view/'),
  ('aa3b4ebe-6dee-45ad-a345-cf2acebf4159', 'Lying Rotator Cuff Exercise', null, 'This is an excercise for problems with the rotator cuff. Primary Infraspinatus, secondary Teres Minor.
Lying on side. Keep elbow on waist and in 90 dgr angle. Rotate towards stomach. Add weight as fit.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Trix', 'https://wger.de/en/exercise/406/view/'),
  ('8a356e9a-0058-4f60-b8d7-89147c3c371f', 'Lying Triceps Extensions', 'Triceps', '- Starting position for this
practical triceps exercise is lying on a standard bench holding a barbell or two dumbbells in both hands with an overhand grip, hands at shoulder width apart.
- Begin with arms over your upper
chest and elbows bent back at about a 45-degree angle.
- First bend at the elbows and
then allow the upper arm to drop back, bringing the barbell/dumbbells behind your
head and down toward the floor. In terms of upper arm position, the barbell/dumbbells should never be fully above your head, but instead behind it, to
ensure that you’re targeting the triceps.
- Keep the shoulder blades tucked
under, the elbows tight in toward your head and your core active during
this entire movement.', 'Barbell, Dumbbell', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1480/view/'),
  ('9c979645-78d1-44be-92a0-7940430a6a98', 'Lying Triceps Kickback', 'Triceps', 'Set the bench to an 60deg angle. Stand still and rest your upper body on the inclined bench, ensuring a nearly straight line of your entire body. Squeeze your shoulder blades together, so that your elbows are located behind your torso with your upper arms nearly parallel to the floor. Lift the dumbbells until your arms form a straight line. Slowly lower the dumbbells back to the initial position. Initial position corresponds to an rectangular position of upper and lower arms.', 'Dumbbell, Incline bench', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1490/view/'),
  ('1e827ef8-0a01-4b26-9e26-eff9d200acca', 'Machine chest fly', 'Chest', 'seated machine, straight back, slow exercise', null, 'wger', 'CC-BY-SA 4', 'novadani', 'https://wger.de/en/exercise/926/view/'),
  ('ab872d04-ca20-4341-b3c9-76763b25ef42', 'Machine glute extension', 'Glutes', 'A GHD hip extension is one of the best exercises for the glutes. While the exercise mainly targets the glutes, it is also excellent for the lower back, the calves and the hamstrings.', null, 'wger', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1132/view/'),
  ('b5726562-82ed-451a-89d8-8c8b13c5019a', 'Machine Hip Abduction', 'Glutes', 'Technique and Execution
Starting Position
Seated Positioning: Sit in the machine with back against the pad
Leg Placement: Inner thighs against the machine''s padded resistance points
Adjust Machine: Set seat position to align your hip joint with the machine''s pivot point
Movement Technique
Start with legs together or slightly pressed against the inner pads
Slowly push legs outward, spreading them apart
Move until maximum comfortable lateral range is reached
Pause briefly at the outer point of the movement
Slowly return to the starting position with controlled movement
Biomechanical Breakdown
Muscle Engagement
Primary Activation: Gluteus Medius (side hip muscle)
Stabilization: Engages core and lower back muscles
Functional Movement: Mimics lateral leg movement used in walking, sports, and daily activities
Benefits
Strength and Stability
Improves Hip Stability
Reduces Risk of Knee Injuries
Enhances Lateral Movement Capabilities
Targets Often-Neglected Muscle Groups', null, 'wger', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1748/view/'),
  ('41fc6adf-3ad7-4019-8405-94710bd36dfd', 'Machine Incline Chest Press (Custom)', 'Shoulders, Chest', 'Perform Machine Incline Chest Press with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2723/view/'),
  ('3d2adf99-8fe9-45cb-b669-c5b18242e282', 'Machine Lateral Raise', 'Shoulders', 'The machine lateral raise is an isolation exercise that targets the medial (side) deltoid muscle to build wider, more defined shoulders. The machine''s fixed path of motion provides greater stability than dumbbells, making it ideal for beginners or those who want to focus solely on muscle activation.', 'Gym mat', 'wger', 'CC-BY-SA 4', 'roneydya', 'https://wger.de/en/exercise/1654/view/'),
  ('dc87b735-016c-410b-915c-e3521fea4be7', 'Machine Side Lateral Raises', 'Shoulders', 'Machine side lateral raises are an isolation exercise for the side (lateral) deltoids, performed on a machine for stability, targeting the outer shoulder by lifting pads or handles out to the sides to shoulder height, then lowering slowly, keeping elbows slightly bent and traps down to focus on the delts. This exercise helps build shoulder width by preventing swinging and providing constant tension, making it great for beginners or as a finisher.
How to Perform Machine Lateral Raises
Setup: Adjust the seat so your shoulders align with the machine''s pivot point, your chest is against the pad (or back if facing out), and your arms are at a 90-degree angle with the pads/handles.
Starting Position: Grip the handles with a relaxed grip, elbows slightly bent, and shoulders down (depressed) away from your ears.
Lifting Phase: Exhale and lift your arms out to the sides, moving your upper arms laterally, until they are parallel to the floor.
Peak Contraction: Pause briefly at the top, squeezing the side delts, but don''t shrug your shoulders up.
Lowering Phase: Inhale and slowly lower the weight back down with control, resisting the weight on the way down.', null, 'wger', 'CC-BY-SA 4', 'Tierrasverdes', 'https://wger.de/en/exercise/1744/view/'),
  ('564dc73e-e8d4-4fd1-85ab-64dce4dd3ea0', 'March or jog in place', 'Hamstrings, Calves, Glutes, Quads', 'Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'MrAlfaRobot', 'https://wger.de/en/exercise/1584/view/'),
  ('fad49a13-b2a0-4b1f-b262-29b32248257d', 'Marching High Knees', 'Quads', 'A low-impact cardio and mobility exercise that strengthens the hip flexors and improves balance.
- ​Movement: Stand tall and lift one knee toward your chest as high as comfortable.
- ​Arms: Swing the opposite arm forward as you lift your knee, similar to a walking motion.
- ​Core: Keep your abs engaged to maintain an upright posture.
- ​Pace: Perform the movement with control, alternating legs rhythmically.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Anon#2', 'https://wger.de/en/exercise/1965/view/'),
  ('28b65190-cae2-4d15-8f4e-dde0d9cc4d4b', 'Meadows Row', 'Lats, Trapezius', 'The Meadows row is a unilateral row performed with a landmine setup, overhand grip, and staggered stance. Lean your torso forward and grip the barbell. Rest the other forearm on the forward leg. Start this movement by driving the elbow behind you while retracting the shoulder-blade. Keep the working shoulder down. Pull toward your back hip until the elbow is level with your torso.', 'Barbell', 'wger', 'CC-BY-SA 4', 'carlos3c', 'https://wger.de/en/exercise/1304/view/'),
  ('346634cf-3896-4c10-bd66-28fb69d02573', 'Medicine ball booklet crunch', 'Abs', 'Using a medicine ball as an overload will make the exercise heavier.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/976/view/'),
  ('66c7eb38-77b5-4d2f-810f-cddd8d97d5a3', 'Medicine ball twist', 'Obliquus externus abdominis, Abs', 'In a seated position, the torso is rotated from side to side without forcing, approaching the knees and making the ball touch the ground from time to time', 'Swiss Ball', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1089/view/'),
  ('c4185277-1d30-4684-9bc0-024ab7f2336a', 'Mentzer Pulldown', 'Biceps', 'Close grip front facing Pull down, while focusing on Biceps, Increases activation of biceps over the whole range, Avoid activating Lats.', 'Cable machine, Incline bench', 'wger', 'CC-BY-SA 4', 'Mike Mentzer', 'https://wger.de/en/exercise/1971/view/'),
  ('7b1e458f-1857-4c2f-8463-7d67d4b2db93', 'Military Press mit SZ-Bar', 'Shoulders', 'On an SZ-bar grip your hands on the outside of each bend and stand with your arms straight down, palms facing your legs. Pull the bar (bending your arms at the elbow) to your chest, and the push the bar above your head (arms as straight as possible). Return the bar to your chest by dropping your arms at the elbows. Return the bar to it''s origional position (stand with your arms straight down, palms facing your legs.)', 'SZ-Bar', 'wger', 'CC-BY-SA 3', 'mbozi1', 'https://wger.de/en/exercise/418/view/'),
  ('5851e2b1-3a80-42ff-91da-530e6b143a34', 'Modified pulldown', 'Lats', 'With an inclined bench in front of the pulldown machine, use a close-grip to do latfocused pulldowns.', 'Cable machine, Incline bench', 'wger', 'CC-BY-SA 4', 'Rottekongen', 'https://wger.de/en/exercise/1635/view/'),
  ('53324f8e-df38-456f-9b7d-8f3a43f45f31', 'Mountain climbers', null, 'Starting position:
Start in the upright push-up position, aka. the high plank position.Hands should be directly under your shoulders.Keep your head in line with your back, facing the floor.Feet should be about hip-width apart.
Steps:
- Move one knee toward the center of your body, towards your elbows, keeping the other leg extended.
- In a quick jumping movement, straighten the bent leg out and pull the other knee toward your body.
- Keep repeating step 2, alternating legs.
Notes:
Throughout the exercise, your back should remain as straight as possible – avoid a hump or a sagging back.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/996/view/'),
  ('0027b172-a83e-4f79-af47-483302a22c02', 'Muscle up', 'Biceps, Lats', 'The body is then explosively pulled up by the arms in a radial pull-up, with greater speed than a regular pull-up. When the bar approaches the upper chest, the wrists are swiftly flexed to bring the forearms above the bar. The body is leaned forward, and the elbows are straightened by activating the triceps. The routine is considered complete when the bar is at the level of the waist and the arms are fully straight.
To dismount, the arms are bent at the elbow, and the body is lowered to the floor, and the exercise can be repeated.
As a relatively advanced exercise, muscle-ups are typically first learned with an assistive kip. The legs swing (kip) up and provide momentum to assist in the explosive upward force needed to ascend above the bar. More advanced athletes can perform a strict variation of the muscle-up which is done slowly, without any kip. This variation begins with a still dead hang and uses isometric muscle contraction to ascend above the bar in a slow, controlled fashion.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'arson', 'https://wger.de/en/exercise/423/view/'),
  ('0d50ce1e-1731-40e8-82e0-c8f512d0a8c9', 'Neck CARs', null, 'Controlled Articular Rotations. Slow full circles 3 each way. Cervical mobility.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1939/view/'),
  ('d27a93fa-7066-477c-a475-c6b6170831db', 'Neck extension', 'Biceps', 'Unilateral triceps exercise with your back to the pulley, with the pulley at the top', 'Cable machine, SZ-Bar', 'wger', 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1717/view/'),
  ('8bffd3b2-663a-4617-9d95-dce24e795470', 'Neck half circles', null, 'Starting position:
Start sitting or standing. Lean your head against one of your shoulders, but don''t push.
Steps:
In one slower fluid motion and with your head relaxed and not pushing in any direction:
- bring your head down toward your chest.
- then lean back aganst your other shoulder.
- then back toward the chest again.4.and finally toward the starting position.
Keep repeating this.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1017/view/'),
  ('cbc5fbc9-9bca-4766-941d-4b6903d4a521', 'Negative Crunches', 'Abs', 'Sit yourself on the decline bench and fix your legs. Cross your arms over the chest and bring with a rolling movement your upper body up, go now without a pause and with a slow movement down again. Don''t let your head move during the exercise.', null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/427/view/'),
  ('3cad7b92-a16b-45dc-a53e-d6a01a158f8e', 'Neutral Grip Lat Pulldown', 'Lats', 'Lat pull downs with a neutral grip on the bar.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1510/view/'),
  ('eaa7927e-6ea0-4fd5-bbcd-525fe90a184b', 'Neutral-grip chest pulldown', 'Biceps, Lats, Serratus anterior', 'The lat pulldown is an important exercise for strengthening the back and improving posture, which can contribute to a healthier life. To perform this exercise correctly and avoid injury, it is important to follow a few key steps:
-
Position yourself in front of the cable machine with your knees slightly bent and your feet on the floor.
-
Grip the cable handle with your palms facing each other and your hands shoulder-width apart.
-
Pull the handle down until it touches or comes close to your chest, holding the position for one or two seconds.
-
Slowly raise the handle back to the starting position, making sure to keep your arms and hands straight and your back straight throughout the movement.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Franpol', 'https://wger.de/en/exercise/1136/view/'),
  ('15fda45b-108b-4b28-bfe5-d0e55a0914bf', 'Neutral-grip pull-ups or TRX rows', 'Lats', '-
Pull-Up: Vertical Pull — Focuses more on the Lats (back width).
TRX Row: Horizontal Pull — Focuses more on the Rhomboids/Traps (mid-back thickness and posture).', 'Pull-up bar', 'wger', 'CC-BY-SA 4', '54str', 'https://wger.de/en/exercise/1738/view/'),
  ('10b0684c-1c48-4be6-913e-19bf1419107b', 'No Leg Drive Dumbbell Chest Press', 'Chest', 'Set up for a normal Dumbbell chest press but lift your leg ups straight or put them on another bench to remove the leg drive.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1461/view/'),
  ('853e4429-da4a-492d-b042-5c124282c005', 'No push-up burpees', null, 'Starting position:
Stand straight, feet hip-width apart.
Steps:
- Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight.
- Keeping your hands on the floor, jump your legs backward into high plank position.
- Jump your feet forward to return to the squat position.
- Jump up.
- Repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/998/view/'),
  ('9b0f7101-b78a-4c47-b680-fbef15469a8a', 'Nordic Curl', 'Hamstrings', 'The Nordic hamstring curl is one of the best lower-body exercises to build posterior leg strength, improve knee health, and prevent injury.', null, 'wger', 'CC-BY-SA 4', 'karly', 'https://wger.de/en/exercise/910/view/'),
  ('ac00021c-12f9-4827-8003-ea07de980b76', 'Omni Cable Cross-over', 'Chest', 'Adjust the weights based on the
motion. When pulling from top to bottom, increase the weight by 20% to 40%
more than the bottom-to-top motion. This accounts for the fact that when
operating from top down, the upper chest muscles are naturally weaker than
the lower chest muscles. So, adjust your weight stack to
compensate.
- Position one cable at a high
setting and the other at the lowest level setting. Get into a staggered
stance in between the cable towers.
- For the cable set low, pull it
upward and across your body. This effectively targets the upper chest.
- For the cable set high, draw it
downward and across your body. This will primarily engage the lower chest.
Once you’re done, swap the
positions of the cables. Change the previously high cable to the lowest
position and vice versa. Repeat the exercise sequence, ensuring you’re
targeting both chest regions effectively.', 'Cable machine, SZ-Bar', 'wger', 'CC-BY-SA 4', 'Moffi', 'https://wger.de/en/exercise/1484/view/'),
  ('6b6c69bc-0b1e-4b2f-ab61-4945eb18047e', 'One Arm Bent Row', 'Lats', 'One arm bent over row on cable with a machine', 'Cable machine', 'wger', 'CC-BY-SA 4', 'anto.kreegyr', 'https://wger.de/en/exercise/1186/view/'),
  ('5ed12527-c8be-4e86-8f2a-cf9dd4781f5b', 'One Arm Overhead Cable Tricep Extension', 'Triceps', 'Set the pulley at the bottom of the cable machine and grab onto it without using any attachments. Extend the cable directly overhead.
While keeping your back straight and upper arm stationary, lower the cable behind your head until you feel a good stretch in your triceps, and then extend it back upward until your elbow is locked out.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'AlucardEvil40', 'https://wger.de/en/exercise/1668/view/'),
  ('f8d69dd4-3c35-49c7-8cbe-f0132eca4c52', 'One Arm Triceps Extensions on Cable', 'Triceps', null, 'Cable machine', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/803/view/'),
  ('8911c37d-8907-4077-b883-86a7c5fcb606', 'One armed push-ups', 'Chest, Triceps', 'Perform push-ups with one hand, alternating the sides', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1293/view/'),
  ('d8ec22e5-8575-483f-bd66-5203fd4bfe84', 'One-Arm Heavy Row', 'Lats', 'Execution
-
Rowing phase (concentric):
- Pull the dumbbell toward your lower chest or waist, leading with your elbow.
- Keep your torso stable — avoid twisting or rotating your shoulders.
- Pause at the top and squeeze your lats.', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1701/view/'),
  ('d7d4fc16-08cd-4568-87e7-d9e4e2f77393', 'one-handed kettlebell curls', 'Biceps', 'Standing with the kettlebell in one hand and bent at the elbow, start from a fully extended position until your hand reaches shoulder height. To perform the movement correctly, try not to push with your back or body.', 'Kettlebell', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/975/view/'),
  ('164b83aa-195e-4eed-b820-b81df950d9bb', 'Open Book', null, 'Basic exercise
- Focus: enhances thoracic mobility and
spinal segmentation while opening the shoulders and chest.
- **Position:**kneeling on the floor with your right side facing a wall. Hips are square and stable, with the right knee down and the left foot forward. Lengthen your spine and align your head comfortably.
Begin with your arms relaxed and open in front of your chest, palms
facing each other and hands apart.
- Inhale
to initiate the movement, allowing your left arm —the one farther from
the wall— to open outward and backward. Lead the twist from your thoracic
spine, rotating your upper back progressively while keeping your pelvis
still.
- Exhale as you complete the rotation, guiding your left hand
toward the wall as your gaze follows your hand.
- Return by inhaling and
slowly bringing your arm forward, reversing the spinal rotation segment
by segment.
- Repeat on the opposite side.
Progression
- **Position:**kneeling on the floor with your right side facing a wall. Left knee down and right foot forward.
- Before the basic exercise: inhale, exhalewhile moving the right arm along the wall with a circle upwards and backwards, inhalewhile bringing back the arm.
- Basic exercise.
- Repeat on the opposite side.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'teus_ergaster', 'https://wger.de/en/exercise/1822/view/'),
  ('c7058ff8-ca3b-4822-abdb-6341ce37c4d1', 'Overhand Cable Curl', 'Biceps', 'Hands at shoulder height, curl arms in toward head, then back out.', 'Cable machine', 'wger', 'CC-BY-SA 3', 'ThisGirl0819', 'https://wger.de/en/exercise/439/view/'),
  ('2500c212-6f14-4a8d-a997-04e9e7c04116', 'Overhead Barbell Press', 'Shoulders', '- Setup: Stand with feet together and grip the bar slightly wider than shoulders.
- Position: Rest the bar on your upper chest.
- Press: Brace your core and push the bar straight up until your arms lock out.
- Finish: Control the bar back down to your chest.
- https://youtu.be/ZXpdJOLNoWw?si=u27cGyODoblXHBu1', 'Barbell', 'wger', 'CC-BY-SA 4', 'nishant0712', 'https://wger.de/en/exercise/1893/view/'),
  ('f2e17c8d-7285-4fd5-bfe8-26f407802850', 'Overhead Cable Tricep Extension', 'Triceps', 'Use rope handle with your back against the cable machine. Straighten your arms until they are filly extended and reverse the motion resisting on the negative.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1513/view/'),
  ('f4467e9a-9bb1-4e93-bec6-10a5d7738ffb', 'Overhead Press', 'Shoulders', null, 'Barbell', 'wger', 'CC-BY-SA 4', 'Vazco', 'https://wger.de/en/exercise/687/view/'),
  ('993c7f0c-729b-4834-a0f5-67d126d92fbf', 'Overhead Press Isometric', 'Shoulders, Triceps', 'An isometric overhead press involves holding a weight statically overhead or pushing against an immovable object at a specific point in the press without moving the joint.', 'Barbell', 'wger', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2537/view/'),
  ('bc45125b-58da-4ee9-8895-16a7b930b789', 'Overhead Squat', 'Glutes, Quads', 'The barbell is held overhead in a wide-arm snatch grip; however, it is also possible to use a closer grip if balance allows.', null, 'wger', 'CC-BY-SA 4', 'geraldbaeck', 'https://wger.de/en/exercise/441/view/'),
  ('c5797bdf-1aa1-4d51-9775-c929ec5a2aaf', 'Overhead Triceps Extension', 'Trapezius', 'Overhead Triceps Extension with EZ Bar – Quick Guide
The overhead position emphasizes the long head of the triceps (because it''s stretched under load), the exercise does engage all three triceps heads (long, lateral, and medial) to some degree during extension.
- Setup:
Sit on a bench (or stand) and hold an EZ bar with a narrow, overhand
grip. Lift the bar overhead, arms fully extended. Keep your core tight
and elbows close to your head.
- Execution:
Slowly lower the bar behind your head by bending your elbows until they
reach ~90°. Keep elbows pointed forward (not flaring out).
- Finish: Extend your arms back up to the starting position, squeezing your triceps at the top.
Tips:
- Control the movement to avoid straining your shoulders.
- Use a moderate weight for full range of motion.
- Keep your back straight and avoid arching.', 'SZ-Bar', 'wger', 'CC-BY-SA 4', 'benjamin.yildiz@proton.me', 'https://wger.de/en/exercise/1519/view/'),
  ('e56f2970-e4c9-45eb-8e8c-52abb590e7a6', 'Pallof Press', 'Shoulders, Glutes, Obliquus externus abdominis, Abs, Serratus anterior, Trapezius', 'The Pallof press is an anti-rotation exercise that trains the larger and smaller muscles around the spine to resist rotation.
- Stand parallel to the cable machine or to the anchor point to the
resistance band and clasp with the handle or band with both hands.
- Make sure your torso is front on and bring your hands to the center of your chest and slowly press out.
- Slowly return your hands to the chest and repeat.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'prevail90', 'https://wger.de/en/exercise/1194/view/'),
  ('934856f3-6eb3-4b37-9536-0ff67a6aa036', 'Parallel Bar Hold', 'Shoulders, Chest, Triceps', '- Stand between a set of parallel bars.
- Place your hands, knuckles outwards, on the bars.
- Push down on your hands to lift yourself off the floor.
- Hold yourself in this position with your arms straight for the required time.', null, 'wger', 'CC-BY-SA 4', 'Croak6728', 'https://wger.de/en/exercise/1808/view/'),
  ('17dd0986-5248-410d-89a4-9268282d103b', 'Patadas traseras', 'Triceps', 'The dumbbell kickback is a popular strength training exercise that targets the triceps muscles in the back of your upper arms. It helps strengthen and tone the triceps, contributing to overall arm strength and aesthetics.
Among the exercises that work the arm muscles, kickback and its variations are very effective. You can easily apply these exercises with dumbbells, cables or resistance bands.', 'Bench, Dumbbell', 'wger', 'CC-BY-SA 4', 'Mariano_O', 'https://wger.de/en/exercise/1703/view/'),
  ('6441ff9e-037e-48d9-8800-67b430dc8e37', 'Pause Bench', 'Chest', 'Lower the bar to your chest and pause (but do not rest) there for 2 seconds. Press back up. use the same weight you would on bench press, but perform only single reps. Total the number of reps you did in one set of bench press (if you did 3 sets of 8 do 8 sinlge pause bench reps.', 'Barbell, Bench', 'wger', 'CC0', 'Mens Fitness', 'https://wger.de/en/exercise/445/view/'),
  ('1b329beb-fcda-4471-ba70-eea62da410dd', 'Pause Hack Squats', 'Quads', 'Hack Squats but with a 1-2s pause at the bottom of the movement. This makes sure that there is no more elastic energy stored in the muscles.', null, 'wger', 'CC-BY-SA 4', 'Expenses7000', 'https://wger.de/en/exercise/1464/view/'),
  ('a4c97a23-f044-4095-a041-94d92ffe44bd', 'Paused Squats', 'Quads', 'Use the same technic as your normal squat. Except that you make a pause at the bottom of the squat for about 1-2 seconds, in other words a bit longer than your normal squat.', 'Barbell', 'wger', 'CC-BY-SA 4', 'bbk', 'https://wger.de/en/exercise/2662/view/'),
  ('71b9da1a-ac07-49c8-8b2d-7179032181fd', 'Pec Deck', 'Chest', 'Pectoral issolation exercise - full range of motion is best with full contraction and slow negative', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1904/view/'),
  ('e797ca42-f9fc-480a-8f48-7f6905978c72', 'Pec deck rear delt fly', null, 'Seated rear delt fly on pec deck machine (facing the machine and extending arms backwards, the hands should be at the height of the shoulders)', null, 'wger', 'CC-BY-SA 4', 'eufvksruh', 'https://wger.de/en/exercise/1775/view/'),
  ('748e9635-7958-4a41-b1ed-93de74c7ef72', 'Pendelay Rows', 'Lats, Trapezius', 'Back excercise with a barbell with a starting position which is in a bent over position with the back paralell to the ground. The barbell is on the ground at chest level.For the movement grab the barbell at shoulder width grip and pull towards your chest without losing the bent over position and without moving anything but your arms', 'Barbell', 'wger', 'CC-BY-SA 3', 'Nallitnas', 'https://wger.de/en/exercise/448/view/'),
  ('daaf1459-e748-4c95-8990-ed3101b2e20d', 'Pendular hack', null, 'Pendulum hack, made on a pendulum machine', null, 'wger', 'CC-BY-SA 4', 'polloperro', 'https://wger.de/en/exercise/1521/view/'),
  ('ffdb4806-d64e-474b-8ce5-8df9a57fb9c7', 'Pendulum Squat', 'Quads', 'Place your feet in the middle of the plate at about shoulder width. Tense your torso. Keep your neck relaxed.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'schweezer', 'https://wger.de/en/exercise/1527/view/'),
  ('7ae1aca7-cdd4-4a81-b22c-f31778462b6b', 'Perpendicular Unilateral Landmine Row', 'Shoulders, Trapezius', 'Using a landmine attachment with the barbell running at 90 degrees to either side, hinge slightly at the hips and grip the barbell by the plate sleeve. Raise the barbell to chest height, with your upper arm parallel to the floor at the top of the movement.', 'Barbell', 'wger', 'CC-BY-SA 4', 'CptnFatbeard', 'https://wger.de/en/exercise/1580/view/'),
  ('91adc5c9-bdeb-4ed8-b261-b7fcd3157330', 'Pigeon Stretch', null, 'View the video to undestand the exercise', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1872/view/'),
  ('24791f79-e5e3-4ef2-ac97-5832302172bb', 'Pike Hold (Floor)', 'Shoulders, Serratus anterior', 'A static bodyweight support with both hands and feet on the floor and hips raised in a pike position. Place your hands and feet securely on the floor, then raise your hips. Keep your elbows straight and actively push the floor away through your shoulders. Maintain a controlled, stationary position without bending your elbows, lowering your head for push-up repetitions, or raising your feet onto a surface. Hold for up to 30 seconds. Stop earlier for loss of alignment, loss of active shoulder support, or pain. Record actual seconds, hand and foot spacing, and alignment. This is the floor variation, not a pike push-up or an elevated-feet pike hold.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'nalhilal', 'https://wger.de/en/exercise/2691/view/'),
  ('3b96a05b-9705-48da-b43e-6e098234bb35', 'Pike Push Ups', 'Chest', 'Push Up performed from a pike position (optional to have feet elevated).', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Nash', 'https://wger.de/en/exercise/454/view/'),
  ('abd2854b-114a-4584-8746-30bd40127863', 'Pin Bench Press BB', 'Chest, Triceps', '- Set security pins to about the height of your sticking point
- Lower the bar, rest on the pins for 1s while holding tension
- Move bar up with maximum force', 'Barbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1436/view/'),
  ('a33ba0c7-1680-4e42-a84e-aecc18c5d75b', 'Pin OHP', 'Shoulders, Triceps', '- Set security pins to the height of your lower chin
- Rest bar on pins keeping tension
- Raise bar over head', 'Barbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1439/view/'),
  ('96f9d74a-7bf4-4ec1-9cd6-c62c13cf7b67', 'Pin Squat', 'Hamstrings, Glutes, Quads', '- Set security pins to about the height of your sticking point
- Lower the bar, rest on the pins for 2s keeping tension
- Stand up with maximum force', 'Barbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1437/view/'),
  ('fe04cf35-1af5-4b51-89d4-c38d7eaa0db1', 'Pistol Squat', 'Hamstrings, Glutes', '- Stand with feet hip-width apart, toes pointed forward, and chest tall.
- Extend your leg straight out; extend both arms in front of you, at shoulder level. Brace your core and look straight ahead.
- Slowly squat down.
- (optional) pause at the bottom.
Keep your (free) leg and arms extended for the whole duration.', null, 'wger', 'CC-BY-SA 3', 'minifigmaster125', 'https://wger.de/en/exercise/456/view/'),
  ('ec9dca8d-1456-430a-abed-70b8bab4779a', 'Pistol squats right', 'Glutes, Quads', '- Stand on one leg, with your other leg straight and slightly forward.
- Bend one knee slowly, descending into a squat and keeping your back and your other leg straight.
- Slowly raise yourself from the squat, straightening the bent knee and keeping the other leg straight.
- Repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1020/view/'),
  ('a82944ae-24f4-4f7a-8aac-af251f6907e5', 'Planche Lean Hold', 'Shoulders, Serratus anterior', 'A straight-arm calisthenics static hold where you assume a plank position and lean the shoulders as far forward as possible past the wrists with protracted scapulae and a hollow body.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'ege', 'https://wger.de/en/exercise/2532/view/'),
  ('c9e57bbe-e839-44c6-861d-1c8dd2845e36', 'Plank', 'Obliquus externus abdominis, Abs', 'Get into a position on the floor supporting your weight on your forearms and toes. Arms are bent and directly below the shoulder.
Keep your body straight at all times and hold this position as long as possible. To increase difficulty an arm or leg can be raised while performing this exercise.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 3', 'YYCfit / BFad07', 'https://wger.de/en/exercise/458/view/'),
  ('4f5de647-eb73-4394-84a7-469d02a96de8', 'Plank Jacks', 'Glutes, Obliquus externus abdominis, Abs', 'Jumping jacks from the plank position.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'jayninja', 'https://wger.de/en/exercise/1489/view/'),
  ('12418067-6cb5-44db-8973-b5be25c0146b', 'Plank Reach', 'Abs', 'Position your body in plank position, keeping your eyes on the ground. Raise one arm in front of you and return it. Repeat with the other arm. Raise and return slowly while keeping your body as still as possible.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1766/view/'),
  ('75d730d0-3b26-4a25-8f1a-7119a98e02ef', 'Plank Shoulder Taps', 'Shoulders, Glutes, Abs', 'In the correct plank position, place your feet slightly wider than shoulder-width apart. alternately lift and touch the opposite shoulder with one hand.', 'Gym mat', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1091/view/'),
  ('94f2dea6-b336-41b2-a438-3ab7b13adbf7', 'Plank with Alternating Leg Lift', 'Glutes', 'In a plank position, lift one leg alternately.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1410/view/'),
  ('e75629ed-4991-4a48-984c-b297f3f9fb58', 'Plank-to-Elbow Extension', 'Shoulders, Abs, Triceps', 'The Plank-to-Elbow Extension is a dynamic exercise that combines the plank with an elbow extension movement', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'clafal', 'https://wger.de/en/exercise/1406/view/'),
  ('f397656d-6f26-47c6-9e4c-221687f3f2fa', 'Plantarflexion Stretch with Band', null, 'This stretch is for the ankles, as well as Tibialis anterior.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'erikocobra', 'https://wger.de/en/exercise/1275/view/'),
  ('493fb1ac-c45a-4b18-bcbb-58b809881e6f', 'Plate Pinch Hold', 'Shoulders', 'The plate pinch hold is a grip strength exercise designed to target the forearms and improve grip endurance. Select one or two weight plates (smooth-edged plates work best) and pinch them together between your thumb and fingers. Hold the plates with your arm straight down by your side or extended slightly in front of you. Maintain the hold for as long as you can, keeping your shoulders relaxed and your grip firm. This exercise can be done for time or repetitions.', null, 'wger', 'CC-BY-SA 4', 'hpmbala@gmail.com', 'https://wger.de/en/exercise/1430/view/'),
  ('5d5122e0-65f3-4afc-ac36-21955e2c7dde', 'Plate-Loaded Lat Pulldown', 'Lats', 'Sit at a plate-loaded (lever) lat pulldown machine with your thighs secured under the pads. Grip the handles overhead with arms fully extended. Pull the handles down toward your upper chest by driving your elbows down and back, squeezing your lats at the bottom. Return slowly to full extension. Resistance comes from weight plates loaded on the machine''s lever arms rather than a cable stack.', null, 'wger', 'CC-BY-SA 4', 'trs1800', 'https://wger.de/en/exercise/2623/view/'),
  ('0e8fd83f-4e97-4749-b5fd-da9d0e85e97a', 'Posterior Pelvic Tilt', 'Abs', 'Lie on your back with knees bent, feet flat on the floor. Flatten your lower back against the floor by tilting your pelvis posteriorly, engaging your abs and glutes. Hold 5 seconds, release. This retrains pelvic positioning to counter anterior pelvic tilt.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Raj', 'https://wger.de/en/exercise/2488/view/'),
  ('52dec48d-25a4-4a78-b66b-ad6a773e143a', 'Power Clean', 'Chest', 'Olympic weight lifting', 'Barbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/683/view/'),
  ('7cd76565-8a8f-4658-98f1-253af9d8bb39', 'Preacher Curl - Externally Rotated', 'Biceps', 'Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body away from the weight', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1658/view/'),
  ('4baa4962-64bd-434f-b2ed-0c3c88099841', 'Preacher Curl - Internally Rotated', 'Biceps', 'Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body towards the weight', 'Dumbbell', 'wger', 'CC-BY-SA 4', 'Shiladree', 'https://wger.de/en/exercise/1657/view/'),
  ('d5fb6606-4832-4216-bc0a-36955b5f741f', 'Preacher Curl Isometric', 'Biceps', 'An isometric preacher curl is a static strength exercise where you hold a fixed position on a preacher pad or and inclined bench under tension without moving the joint.', 'Dumbbell, SZ-Bar', 'wger', 'CC-BY-SA 4', 'HexoctusEngineering', 'https://wger.de/en/exercise/2539/view/'),
  ('7eb52939-0e33-4319-829d-d8e142fc74d9', 'Preacher Curl Machine', 'Biceps', 'Adjust the seat so that your armpits rest on the top edge of the pad and your upper arms lie flat on it. Grip the handles with your palms facing up.
Curl the handles up by bending your elbows, without lifting your upper arms off the pad or leaning back. Squeeze the biceps briefly at the top, then lower the handles slowly until your arms are almost straight.', null, 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/2633/view/'),
  ('dd52fb99-9426-4a78-b446-20a8e3e4ec47', 'Preacher Curls', 'Brachialis', 'Place the EZ curl bar on the rest handles in front of the preacher bench. Lean over the bench and grab the EZ curl bar with palms up. Sit down on the preacher bench seat so your upper arms rest on top of the pad and your chest is pressed against the pad. Lower the weight until your elbows are extended and arms are straight. Bring the weights back up to the starting point by contracting biceps. Repeat', 'SZ-Bar', 'wger', 'CC-BY-SA 3', 'cgoob883', 'https://wger.de/en/exercise/465/view/'),
  ('f9866335-e489-404b-84b5-248fb8512702', 'Prisoner Squat', 'Glutes, Quads', 'Stand upright with your chest slightly raised, your feet hip-width apart and your toes pointing straight ahead.
Bring your hands to the back of your head with your fingers slightly interlaced and your elbows pointing to the side. Push your hips back and bend your knees, keeping your upper body as upright as possible.
Push your knees outwards, they must never point towards each other. If your upper body moves slightly forward, make sure that it does not bend. Always keep your elbows level with your ears by tensing the muscles between your shoulder blades. If you are flexible enough, you can sink down until your buttocks touch your calves.
However, make sure that you do not bend your spine.
Before this happens, reverse the movement and use your heels and glutes to push yourself upwards with so much momentum that your feet lift off briefly and you do a little hop.
If necessary, correct the position of your feet, arms and upper body before you move on to the next repetition.
Translated with www.DeepL.com/Translator (free version)', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1208/view/'),
  ('1cfa720a-eb50-4c8a-8e19-627f8efe6928', 'Prone Leg Kickback (Custom)', 'Glutes', 'Lie face down with legs straight, kick both legs back, squeeze the glutes, keep the lower back flat, move slowly under control, ten reps per set, breathe steadily.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2759/view/'),
  ('9cb69afc-7a44-4a22-b9a9-7bde8aca5b11', 'Prone Scapular Retraction - Arms at Side', 'Trapezius', 'Lying on stomach with head on towel.
Stretch arms straight out to your sides.
Slowly lift your arms, pulling your shoulderblades together, hold for 3 seconds.', null, 'wger', 'CC-BY-SA 4', 'donaddon', 'https://wger.de/en/exercise/468/view/'),
  ('c38b0f69-7f01-4f0f-82cc-e33cdc658f9e', 'Pseudo Planche Push-up', 'Shoulders', 'You should have the shoulder line in front of your wrists an perform a push-up, maintaining the shoulder in the same position', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'vdrb', 'https://wger.de/en/exercise/1284/view/'),
  ('7f834f07-fa7b-46b6-8ffa-45930b0602db', 'Pull Ups on Machine', 'Lats', null, null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/477/view/'),
  ('5e3a322b-98dd-4197-b16f-4ac72c42c223', 'Pull-up Isometric Hold', 'Biceps, Lats, Trapezius', 'Hold the pull-up movement in any position', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'DiscoCop', 'https://wger.de/en/exercise/1537/view/'),
  ('aaa82de1-965c-4182-b415-6e0cce5ab6df', 'Pull-Up Top Position Hold', 'Lats', 'Use a box or bench to get your chin above a pull-up bar with your elbows fully bent and shoulders pulled down. Take your feet off the box and hold that top position still for the set time. Keep your chest up and do not let your chin drop below the bar. This strengthens the hardest part of the pull-up.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'lightking', 'https://wger.de/en/exercise/2731/view/'),
  ('8e420408-0682-4ab6-89f5-2681e54c7ce0', 'Pull-ups', 'Lats', 'Grab the pull up bar with a wide grip, the body is hanging freely. Keep your chest out and pull yourself up till your chin reaches the bar or it touches your neck, if you want to pull behind you. Go with a slow and controlled movement down, always keeping the chest out.', 'Pull-up bar', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/475/view/'),
  ('bbd23eaf-d447-4dce-9b3f-50a60404936f', 'Pull-ups (Custom)', 'Lats', 'Perform Pull-ups with controlled form, keeping tension on the target muscles, pausing briefly at the peak contraction, then returning slowly under control without using momentum.', 'Pull-up bar', 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2715/view/'),
  ('1f490456-b426-4b89-b70c-e155c3571422', 'Pull-Ups (Neutral Grip)', 'Lats', 'Execution
-
Pulling phase (concentric):
- Drive your elbows down and back, pulling your chest toward your hands.
- Keep your shoulders depressed and retracted (avoid shrugging).
- Focus on squeezing your lats and upper back at the top.
-
Top position:
- Chin should clear or reach the level of your hands.
- Pause briefly and contract your lats hard.', null, 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1696/view/'),
  ('be4eb0b6-2c39-4ff5-b57d-419f1687c90f', 'Pull-Ups (Wide Grip)', 'Lats', 'Execution
-
Pulling phase (concentric):
- Drive your elbows down and slightly back, pulling your chest toward the bar.
- Focus on leading with your chest, not your chin.
- Keep your shoulders depressed (avoid shrugging).
-
Top position:
- Chin should clear the bar (or at least reach bar level).
- Pause for a brief squeeze in your lats.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'daiben', 'https://wger.de/en/exercise/1695/view/'),
  ('289bd40b-e3dd-4217-8670-e475771a0ea7', 'Pullback', 'Biceps, Lats', 'Set weight and grip for the cables in the cage. Take a few steps away, bend over, pull and extend the back at the same time.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'cybro', 'https://wger.de/en/exercise/1905/view/'),
  ('9ccd53e0-8392-4e61-91aa-e4e5f4ea339c', 'Pullover', 'Chest', 'Doubling as a back and chest exercise, the Dumbbell Pullover can train both your pecs and lats.', 'Dumbbell', 'wger', 'CC-BY-SA 4', '3leh', 'https://wger.de/en/exercise/1273/view/'),
  ('ad20ef5e-e360-4859-9110-668ee0c24721', 'Pullover Machine', 'Lats', 'Pullover machine, sitting, elbows on pads', null, 'wger', 'CC-BY-SA 4', 'Paul@Chemistry', 'https://wger.de/en/exercise/1384/view/'),
  ('a540925e-fe66-47cc-ae28-ecdce408fb6d', 'Pullup on fingerboard', 'Biceps, Lats', 'Pullup on a choosen edge of a fingerboard / hangboard', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'marcelbader', 'https://wger.de/en/exercise/821/view/'),
  ('adf81065-407c-4dd7-8ec5-920cc5944d58', 'punches', 'Shoulders, Triceps', 'stand stable and throw normal straight punches', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'lh1701', 'https://wger.de/en/exercise/1462/view/'),
  ('a535b8f1-2024-4c5c-b323-f711cbf9773c', 'Push OHP', 'Shoulders, Glutes, Quads', '- Rest bar in front on your shoulders
- Bend knees while keeping upper body straight
- Extend legs pushing the bar overhead with force', 'Barbell', 'wger', 'CC-BY-SA 4', 'M9', 'https://wger.de/en/exercise/1440/view/'),
  ('4284336c-6cfa-4c4d-a440-26b30db035d1', 'Push Press', 'Trapezius', 'Clean your dumbbells onto your shoulders, palms facing in. Take a breath and brace your core. (picture 1)Dip at the knees and use your legs to help (picture 2) press your dumbbells overhead. Lower under control with a slow tempo to your shoulders and repeat.', null, 'wger', 'CC-BY-SA 3', 'sistab2', 'https://wger.de/en/exercise/478/view/'),
  ('f5b84269-18af-4464-a61f-b767cbcd81dc', 'Push-Up', 'Chest', 'The push-up is a fundamental bodyweight exercise that targets the chest, arms, and shoulders while engaging the core for stability. It requires no equipment and is excellent for building upper body strength.
Instructions:
- Start in a plank position with hands placed slightly wider than shoulder-width, feet together, and body in a straight line from head to heels.
- Engage your core and lower your body by bending your elbows, keeping them close to your body or flared slightly outward.
- Lower until your chest nearly touches the ground while maintaining a neutral spine.
- Push through your palms to return to the starting position, fully extending your arms.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Settebello', 'https://wger.de/en/exercise/1551/view/'),
  ('a9633731-1d86-4b4a-996f-33a1dee0b0e1', 'Push-up rotations', 'Chest, Triceps', 'Starting position:
Get into the starting push-up position, with your hands and toes touching the ground and back, arms and legs straight. To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.
Steps:
- Perform a standard push-up:
1.a Bend arms until chest almost touches the ground, making sure the back is straight.1.b Use your arms to lift yourself back up to starting position.
- Rotate your body to the side so that the back is straight, the bottom hand supporting the body is fully extended, and only the bottom hand and foot touch the floor.
- Repeat, changing sides at step 2 each time.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/985/view/'),
  ('50037aaf-34f1-4018-b504-206623b77c46', 'Push-Ups | Decline', 'Chest', 'Decline push-ups are another modified version of the traditional push-up that target the upper body muscles in a different way. To perform a decline push-up, elevate your feet on an elevated surface, such as a bench, chair, or step, while placing your hands on the ground in a push-up position. Lower your body towards the ground while maintaining a straight line from your shoulders to your ankles, and then push back up to the starting position.
Unlike the inclined push-up, the decline push-up places more emphasis on the shoulders and triceps, while still engaging the chest muscles to a lesser extent. By elevating your feet, you increase the difficulty of the exercise by placing more weight on your upper body, forcing your shoulders and triceps to work harder to push your body back up. The decline push-up can be a great way to challenge your upper body strength and improve your ability to perform other push-up variations. As with any exercise, be sure to use proper form and start with a height that is appropriate for your strength and fitness level.', 'Bench, Incline bench', 'wger', 'CC-BY-SA 4', 'anon1337', 'https://wger.de/en/exercise/1112/view/'),
  ('4aa7e2a7-86ad-4322-978f-ff8b391f556c', 'Push-Ups | Incline', 'Chest', 'Inclined push-ups primarily target the chest muscles (pectoralis major and minor), but also work the triceps, shoulders, and core to a lesser extent. Because the upper body is elevated, the incline push-up places less emphasis on the triceps compared to regular push-ups, which may be beneficial for individuals looking to specifically target their chest muscles.', 'Bench, Incline bench', 'wger', 'CC-BY-SA 4', 'anon1337', 'https://wger.de/en/exercise/1111/view/'),
  ('bd141adb-b9ad-4038-b11f-1db8665f72bc', 'Push-Ups | Parallettes', 'Chest', 'Parallettes push-ups are a variation of the traditional push-up that are performed with the hands on parallel bars, known as parallettes. To perform a parallettes push-up, assume a push-up position with your hands on the parallettes and your feet on the ground. Lower your body towards the ground while keeping your elbows close to your sides, and then push back up to the starting position.
Parallettes push-ups place more emphasis on the chest and shoulders compared to traditional push-ups, as they allow for a greater range of motion in the shoulder joint. This increased range of motion can also help to improve shoulder stability and mobility. Additionally, parallettes push-ups engage the core muscles more than traditional push-ups, as the instability of the parallettes requires greater activation of the core muscles to maintain proper form.
The added challenge of balancing on the parallettes also requires greater upper body strength and control, making parallettes push-ups a more advanced variation of the traditional push-up. They can be a great way to challenge yourself and add variety to your upper body workout routine. As always, be sure to use proper form and start with a level that is appropriate for your strength and fitness level.', null, 'wger', 'CC-BY-SA 4', 'anon1337', 'https://wger.de/en/exercise/1113/view/'),
  ('2867cd51-f911-47db-9ea5-ca09aa44ca8f', 'Quad Sets', null, 'What Are Quad Sets?
Quad sets are a fundamental exercise used in knee rehabilitation. They focus on strengthening the quadriceps muscles located at the front of the thigh. This exercise is particularly beneficial for individuals recovering from knee injuries or surgeries.
How to Perform Quad Sets
Steps to Execute Quad Sets
- Positioning: Sit or lie down with your legs straight.
- Tightening: Tighten the quadriceps muscles while keeping the leg straight. You should see the kneecap move upward.
- Holding: Maintain the contraction for about 5 seconds.
- Releasing: Relax the muscle after the hold.
- Repetitions: Aim for 10 to 15 repetitions, gradually increasing as strength improves.
Tips for Effective Quad Sets
- Ensure no other muscles are contracting to assist the quadriceps.
- Perform the exercise on a flat surface, like a bed or couch, with a towel or pillow under your heel for comfort.
- It is recommended to do these exercises multiple times a day, especially during the early stages of recovery.
Benefits of Quad Sets
- Restores Muscle Function: Helps rebuild strength in the quadriceps.
- Improves Stability: Enhances stability in the knee joint.
- Increases Range of Motion: Aids in regaining mobility after injury or surgery.
Incorporating quad sets into your rehabilitation routine can significantly aid in recovery and improve overall knee function.', 'Gym mat', 'wger', 'CC-BY-SA 4', 'aboksz', 'https://wger.de/en/exercise/2617/view/'),
  ('03ff5a69-97d8-4778-9d92-6b8dc2ec1172', 'Quadratus Lumborum Stretch (Custom)', 'Calves', 'Stand and side-bend slowly to one side, feel a gentle stretch along the waist, hold for thirty seconds, switch sides, move gently and stop if you feel sharp pain.', null, 'wger', 'CC-BY-SA 4', 'ruochenma', 'https://wger.de/en/exercise/2757/view/'),
  ('d37ef608-01e1-4ac0-8b41-a23953183328', 'Quadriceps Stretch', 'Quads', 'Stand on one leg (hold onto a wall if necessary). Use your hand to grasp the ankle of your other leg and gently pull your heel toward your buttocks. Make sure your knees stay close together and that you push your pelvis slightly forward (avoid arching your back).', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'tobias08', 'https://wger.de/en/exercise/2687/view/'),
  ('80c167b9-3749-48a1-8686-fc2163a1e7fb', 'Quadriped Arm and Leg Raise', 'Shoulders, Glutes, Serratus anterior, Trapezius', 'In this exercise, the back muscles and the muscles of the back of the leg and back of the arm are activated by lifting the crossed arm and leg at the same time in the crawling position. It also improves balance and proprioception. The movement is done symmetrically.
- Get into a crawling posture.2. Draw your abdomen in, then raise your right leg and left arm.3. You should keep your abdomen in for 8 seconds.4. After 8 seconds, slowly lower your arm and leg.5. Then release your muscle.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'utkb', 'https://wger.de/en/exercise/957/view/'),
  ('2a1f7c0c-c63d-43f1-9934-a209ed405ff8', 'Quadruped Hip Abduction', null, 'Distribute your body weight evenly on all knees and arms.
Keep the torso stable, with the abdomen engaged and the lumbar spine
straight without twisting the back (imagine: a glass on your lower back
won''t fall off). Raise one leg outwards without twisting it.
Pay attention to the right angle at the hips and knees. Always train both sides of the body.
To increase resistance, a resistance band can be used.', 'Resistance band', 'wger', 'CC-BY-SA 4', 'treder', 'https://wger.de/en/exercise/1915/view/'),
  ('25854f7a-485a-4280-a0fa-f024655733b0', 'Quadruped thoracic rotation left', null, 'Starting position:
Start kneeling on all fours, knees shoulder-width apart. Place your left hand behind your head while keeping your right hand outstretched and touching the floor.
Steps:
- On inhale, move your left elbow toward your right hand, keeping your left hand behind your head.
- On exhale, move your left elbow to point up toward the ceiling.
- Repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1028/view/'),
  ('da588c5e-ab8b-42a7-a52c-1e680a484334', 'Quadruped thoracic rotation right', null, 'Starting position:
Start kneeling on all fours, knees shoulder-width apart. Place your right hand behind your head while keeping your left hand outstretched and touching the floor.
Steps:
- On inhale, move your right elbow toward your left hand, keeping your right hand behind your head.
- On exhale, move your right elbow to point up toward the ceiling.
- Repeat.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'tinman', 'https://wger.de/en/exercise/1029/view/'),
  ('a6c2a970-a621-4e03-be1d-4a29118b1687', 'Rack Deadlift', 'Glutes', 'Deadlift to be done using a Smith machine or a free rack. Bar or barbell hould be just right under the knee cap level. Lift using the glutes and through the heels, then come back to starting postion with a control movement of 2 seconds.
This exercise targets mainly the lower back and glutes.', null, 'wger', 'CC-BY-SA 3', 'Mahoney', 'https://wger.de/en/exercise/484/view/'),
  ('046b1e8f-4a11-4579-84d1-ac2833b8ed83', 'Radio Taiso', 'Shoulders, Lats, Quads, Abs', 'Video can be found here : https://www.youtube.com/watch?v=SGPBSqxKGAc
Full-body mobility and dynamic warm-up routine (3–5 minutes) to prepare joints, muscles, and the cardiovascular system for workout.
Movement Flow:
Deep Breathing & Arm Raises: Inhale while raising arms laterally overhead, exhale as you lower them.
Knee Bends: Soft, rhythmic knee flexions synchronized with arm swings.
Arm Circles: Large full-range arm rotations forward, then backward to open up the chest and shoulder girdle.
Chest Expansion: Cross arms in front of the chest and open wide to the sides.
Side Bends: Reach overhead to stretch the lateral torso left and right with a smooth side flexion.
Forward & Back Bends: Gently hinge at the hips to reach forward, then return upright with a mild spinal extension.
Torso Twists: Swing arms side-to-side to rotate the spine and loosen the core.
Ankle Mobility / Light Bounces: Soft heel lifts or light bouncing on toes to warm up lower leg joints and tendons.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Mamo2604', 'https://wger.de/en/exercise/2671/view/'),
  ('6c21c09b-90c8-4e43-a43c-ed566f812784', 'Reach ups', 'Obliquus externus abdominis', 'To perform this exercise, lie on your back with your arms extended overhead. Then, contract your abdominals and lift your torso off the floor while reaching your arms toward the ceiling to "reach" as high as possible. Slowly return to the starting position, controlling the movement. Reach ups strengthen the abdominal muscles and improve the flexibility of the spine. They can be incorporated into a variety of training routines to work on core strength and stability.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'painDpice', 'https://wger.de/en/exercise/1287/view/'),
  ('3f93459a-d06e-465c-85db-2137da759440', 'Rear Delt Raises', null, 'Seated on a bench with the dumbbells on the floor bend over at 45 Degrees and then slowly raise each dumbbell to shoulder height and hold for a couple seconds before lowering to the starting position.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'YYCfit', 'https://wger.de/en/exercise/487/view/'),
  ('2f2192c3-6e95-41b5-9438-2f1497f56767', 'Rear-foot-elevated Hip Flexor Stretch', null, 'Rear-foot-elevated Hip Flexor Stretch
Part of: Limber 11
Source: Joe DeFranco
